library ieee;
use ieee.std_logic_1164.all;
use ieee.std_logic_unsigned.all;

entity Adder is               --add unit
	port(
		a, b: in std_logic_vector(3 downto 0);
		sum: out std_logic_vector(3 downto 0);
		cin: in std_logic;
		cout: out std_logic);
end Adder;

architecture behavior of Adder is
	component f_adder        --Four bit Full-Adder
	port(
		a1, b1: in std_logic_vector(3 downto 0);
		cin1: in std_logic;
		sum1: out std_logic_vector(3 downto 0);
		cout1: out std_logic);
	end component f_adder;

	signal Q1: std_logic_vector(3 downto 0);
	signal Q2: std_logic_vector(3 downto 0);
	signal COU: std_logic;
	signal COUT1: std_logic;

	begin
    U1: f_adder PORT MAP(a1=>a,b1=>b,cin1=>cin,sum1=>Q1,cout1=>COU);
	process(a,b,cin)
		begin
		if(COU = '1')then
			Q2 <= Q1+6;
		elsif(Q1 > 9)then
			Q2 <= Q1-10;
			COUT1 <= '1';
		elsif(Q1 < 10)then
			Q2 <= Q1;
			COUT1 <= '0';
		end if;
	sum <= Q2;
	cout <= COUT1;
	end process;
end behavior;

library ieee;
use ieee.std_logic_1164.all;
use ieee.std_logic_unsigned.all;

entity f_adder is
port(
 a1, b1: in std_logic_vector(3 downto 0);
 cin1: in std_logic;
 sum1: out std_logic_vector(3 downto 0);
 cout1: out std_logic);
end entity f_adder;

architecture behavior of f_adder is
 signal S: std_logic_vector(4 downto 0);
 signal A,B: std_logic_vector(4 downto 0);
 begin
  A <= '0'& a1;
  B <= '0'& b1;
  S <= A + B + cin1;
  sum1 <= S(3 downto 0);
  cout1 <= S(4);
end architecture behavior;
